=== reservations/ReservationService.java
     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.rooms.Room;
     5	import hotel.rooms.Rooms;
     6	import java.math.BigDecimal;
     7	import java.util.List;
     8	
     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    private final Rooms rooms;
    13	    private final ReservationStore store;
    14	    private final PriceCalculator priceCalculator;
    15	    private final List<ReservationListener> listeners;
    16	
    17	    public ReservationService(Rooms rooms, ReservationStore store, PriceCalculator priceCalculator,
    18	            List<ReservationListener> listeners) {
    19	        this.rooms = rooms;
    20	        this.store = store;
    21	        this.priceCalculator = priceCalculator;
    22	        this.listeners = List.copyOf(listeners);
    23	    }
    24	
    25	    public synchronized Reservation create(NewReservation request) {
    26	        if (!request.checkOut().isAfter(request.checkIn())) {
    27	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    28	        }
    29	        if (request.guests() < 1) {
    30	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    31	        }
    32	        Room room = rooms.find(request.roomNumber())
    33	                .orElseThrow(() -> new HotelException(
    34	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    35	        if (request.guests() > room.capacity()) {
    36	            throw new HotelException(
    37	                    ErrorCode.CAPACITY_EXCEEDED,
    38	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    39	        }
    40	        boolean roomTaken = store.all().stream()
    41	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
    42	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
    43	        if (roomTaken) {
    44	            throw new HotelException(
    45	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    46	        }
    47	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    48	        Reservation reservation = new Reservation(store.nextId(), request, price);
    49	        store.save(reservation);
    50	        return reservation;
    51	    }
    52	
    53	    public Reservation find(long reservationId) {
    54	        return store.find(reservationId)
    55	                .orElseThrow(() -> new HotelException(
    56	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    57	    }
    58	
    59	    /** The guest paid: the reservation is confirmed, and the listeners hear about it. */
    60	    public synchronized Reservation confirm(long reservationId) {
    61	        Reservation reservation = find(reservationId);
    62	        if (reservation.status() != ReservationStatus.PENDING) {
    63	            throw notAllowed(reservation, "confirm");
    64	        }
    65	        reservation.confirmPayment();
    66	        Room room = roomOf(reservation);
    67	        listeners.forEach(listener -> listener.confirmed(reservation, room));
    68	        return reservation;
    69	    }
    70	
    71	    /**
    72	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    73	     * reservation was never paid, so nothing comes back).
    74	     */
    75	    public synchronized Reservation cancel(long reservationId) {
    76	        Reservation reservation = find(reservationId);
    77	        if (reservation.status() != ReservationStatus.PENDING
    78	                && reservation.status() != ReservationStatus.CONFIRMED) {
    79	            throw notAllowed(reservation, "cancel");
    80	        }
    81	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    82	        BigDecimal refund = switch (reservation.ratePlan()) {
    83	            case STANDARD -> reservation.amountPaid();
    84	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    85	        };
    86	        reservation.cancel(refund);
    87	        if (wasConfirmed) {
    88	            Room room = roomOf(reservation);
    89	            listeners.forEach(listener -> listener.cancelled(reservation, room));
    90	        }
    91	        return reservation;
    92	    }
    93	
    94	    public synchronized Reservation checkIn(long reservationId) {
    95	        Reservation reservation = find(reservationId);
    96	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    97	            throw notAllowed(reservation, "check in");
    98	        }
    99	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   100	        return reservation;
   101	    }
   102	
   103	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   104	    public synchronized ReservationReceipt checkOut(long reservationId) {
   105	        Reservation reservation = find(reservationId);
   106	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   107	            throw notAllowed(reservation, "check out");
   108	        }
   109	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   110	        return new ReservationReceipt(reservation, roomOf(reservation));
   111	    }
   112	
   113	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   114	    public ReservationReceipt receiptCopy(long reservationId) {
   115	        Reservation reservation = find(reservationId);
   116	        if (!reservation.isPaid()) {
   117	            throw notAllowed(reservation, "issue a receipt for");
   118	        }
   119	        return new ReservationReceipt(reservation, roomOf(reservation));
   120	    }
   121	
   122	    private Room roomOf(Reservation reservation) {
   123	        return rooms.find(reservation.roomNumber()).orElseThrow();
   124	    }
   125	
   126	    private static HotelException notAllowed(Reservation reservation, String operation) {
   127	        return new HotelException(
   128	                ErrorCode.OPERATION_NOT_ALLOWED,
   129	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   130	    }
   131	}
